		ov.mesh = om
		ov.material_override = mat
		ov.cast_shadow = GeometryInstance3D.SHADOW_CASTING_SETTING_OFF
		ov.position = Vector3(0.0, 0.03, 0.0)
		ov.visible = false
		plane.add_child(ov)
		nodes.append(ov)
	shadow_path_overlays[lane] = nodes


