extends Node
var t := 0
var bm = null
func _ready() -> void:
	process_mode = Node.PROCESS_MODE_ALWAYS
	add_child((load("res://scenes/battle.tscn") as PackedScene).instantiate())
func _process(_d: float) -> void:
	t += 1
	if t == 30:
		Config.player_team = Config.Team.PLAYER
		Config._team_rolled = true
		bm = get_tree().get_first_node_in_group("battle_manager")
		bm._start_game_body("后羿", "flash")   # 射手 → 推荐发育路
	elif t > 60 and t % 60 == 0:
		var g = _find(bm, "LaneGuide")
		print("L t=", t, " guide=", (g != null))
		if g:
			var mi := 0
			var pads := []
			for c in g.get_children():
				if c is MeshInstance3D:
					mi += 1
					var m: StandardMaterial3D = (c as MeshInstance3D).material_override
					var bb: AABB = (c as MeshInstance3D).mesh.get_aabb()
					pads.append("%s a=%.2f sz=(%.1f,%.1f,%.1f) col=(%.2f,%.2f,%.2f)" % [(c as MeshInstance3D).mesh.get_surface_count() > 0, m.albedo_color.a, bb.size.x, bb.size.y, bb.size.z, m.albedo_color.r, m.albedo_color.g, m.albedo_color.b])
			print("L   mesh_count=", mi, " role_lane=", bm._lane_for_role(str(bm.hero.role)), " hero_role=", bm.hero.role)
			for p in pads: print("L   ", p)
	if t == 1500:
		get_tree().quit()
func _find(n: Node, nm: String) -> Node:
	if str(n.name) == nm: return n
	for c in n.get_children():
		var r := _find(c, nm)
		if r: return r
	return null
